template <typename UnionPtrType>
IntegerKeyParamPtr IntegerKeyParam::Clone() const {
  switch (tag_) {
    case Tag::kBooleanValue:
      return NewBooleanValue(
          mojo::Clone(data_.boolean_value));
    case Tag::kInteger:
      return NewInteger(
          mojo::Clone(data_.integer));
    case Tag::kLongInteger:
      return NewLongInteger(
          mojo::Clone(data_.long_integer));
    case Tag::kDateTime:
      return NewDateTime(
          mojo::Clone(data_.date_time));
    case Tag::kBlob:
      return NewBlob(
          mojo::Clone(*data_.blob));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, IntegerKeyParam>::value>::type*>
bool IntegerKeyParam::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kBooleanValue:
      return mojo::Equals(data_.boolean_value, other.data_.boolean_value);
    case Tag::kInteger:
      return mojo::Equals(data_.integer, other.data_.integer);
    case Tag::kLongInteger:
      return mojo::Equals(data_.long_integer, other.data_.long_integer);
    case Tag::kDateTime:
      return mojo::Equals(data_.date_time, other.data_.date_time);
    case Tag::kBlob:
      return mojo::Equals(*(data_.blob), *(other.data_.blob));
  }

  return false;
}
